 const baseFormal=N(s.formal)*(s.formalVerified?(N(s.formalMonths)<3?.85:1):.70), formal=baseFormal+(s.formalVerified?N(s.otherFormal):N(s.otherFormal)*.65),income=formal+recognizedInformal;
