function compare(i=idx){let c=evaluate(DB.months[i]),p=i>0?evaluate(DB.months[i-1]):null,diff={},partDiff={};for(let f of FACTORS){diff[f.id]=p?c.points[f.id]-p.points[f.id]:0;partDiff[f.id]=c.parts[f.id].map((v,j)=>({...v,delta:p?v.points-p.parts[f.id][j].points:0}));}return {c,p,diff,partDiff,delta:p&&p.score!==null&&c.score!==null?c.score-p.score:null};}
/* E2 (v5.1): con menos de 12 meses de evidencia o de antigüedad promedio el índice no puede llamarse «sólido»: tope «Perfil en desarrollo». La confianza se muestra junto al número. */
function isDeveloping(s){return N(s.recordMonths)<12||N(s.avgHistoryMonths)<12}
function confidenceOf(s){const q=qualityReport(s),m=N(s.recordMonths);return {pct:q.reliability,months:m,developing:isDeveloping(s),text:`Calidad ${q.reliability}/100`}}
function scoreName(x,s0){if(x!==null&&s0&&isDeveloping(s0)&&x>=750)return 'Perfil en desarrollo';return x===null?'Datos insuficientes':x>=850?'Perfil de crédito muy sólido':x>=750?'Perfil de crédito sólido':x>=620?'Perfil en desarrollo':x>=470?'Requiere atención':'Atención prioritaria'}
